package io.colorsand.ui

import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.RoundRect
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.ClipOp
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.clipPath

/** How far in from each side the tube's body is, in tube widths; the rim at the top sticks out past it. */
internal const val BODY_INSET = 0.065f

/**
 * The candy glass of a tube of [size], in the [palette]'s glass colors: paths and brushes made once per size.
 * Draw [drawBack] behind the sand, [drawFront] over it, then [drawOutline].
 */
internal class TubeGlass(size: Size, palette: Palette) {
    private val w = size.width
    private val h = size.height
    private val inset = w * BODY_INSET
    private val bottom = h - w * 0.03f
    private val stroke = w * 0.055f

    /** The inside of the tube, where the sand goes. */
    val body = Path().apply {
        addRoundRect(
            RoundRect(
                left = inset,
                top = w * 0.05f,
                right = w - inset,
                bottom = bottom,
                topLeftCornerRadius = CornerRadius(w * 0.08f),
                topRightCornerRadius = CornerRadius(w * 0.08f),
                bottomLeftCornerRadius = CornerRadius(w / 2 - inset),
                bottomRightCornerRadius = CornerRadius(w / 2 - inset),
            ),
        )
    }
    private val rim = RoundRect(w * 0.012f, w * 0.0f, w * 0.988f, w * 0.13f, CornerRadius(w * 0.065f))
    private val rimPath = Path().apply { addRoundRect(rim) }

    /** The whole tube's shape, body and rim, for the outline and its glow. */
    private val shape = Path().apply {
        addPath(body)
        addPath(rimPath)
    }

    private val shine = palette.glassShine.alpha
    private val tint = palette.glass

    // Glass looks thicker where it turns away, at both sides.
    private val backBrush = Brush.horizontalGradient(
        0f to tint.copy(alpha = minOf(tint.alpha * 3f, tint.alpha + 0.14f)),
        0.3f to tint.copy(alpha = tint.alpha * 0.6f),
        0.75f to tint.copy(alpha = tint.alpha * 0.5f),
        1f to tint.copy(alpha = minOf(tint.alpha * 3.4f, tint.alpha + 0.18f)),
        startX = inset,
        endX = w - inset,
    )
    // Inner shadow at the sides, over the sand too.
    private val edgeBrush = Brush.horizontalGradient(
        0f to Color.Black.copy(alpha = 0.16f),
        0.12f to Color.Transparent,
        0.86f to Color.Transparent,
        1f to Color.Black.copy(alpha = 0.2f),
        startX = inset,
        endX = w - inset,
    )
    private val streakBrush = Brush.verticalGradient(
        0f to Color.White.copy(alpha = (shine * 3.2f).coerceAtMost(0.85f)),
        0.55f to Color.White.copy(alpha = (shine * 1.6f).coerceAtMost(0.5f)),
        1f to Color.Transparent,
        startY = w * 0.2f,
        endY = h * 0.84f,
    )
    private val rimBrush = Brush.verticalGradient(
        listOf(Color.White.copy(alpha = (shine * 2.6f).coerceAtMost(0.8f)), tint.copy(alpha = (tint.alpha * 2.5f).coerceAtMost(0.6f))),
        startY = 0f,
        endY = rim.bottom,
    )

    fun drawBack(scope: DrawScope) = with(scope) {
        drawPath(body, backBrush)
    }

    fun drawFront(scope: DrawScope) = with(scope) {
        drawPath(body, edgeBrush)
        // Main streak of light down the left, a thinner one on the right.
        drawRoundRect(streakBrush, Offset(w * 0.17f, w * 0.2f), Size(w * 0.1f, h * 0.64f), CornerRadius(w * 0.05f))
        drawRoundRect(
            Color.White.copy(alpha = (shine * 1.5f).coerceAtMost(0.45f)),
            Offset(w * 0.75f, w * 0.3f),
            Size(w * 0.045f, h * 0.3f),
            CornerRadius(w * 0.03f),
        )
        drawCircle(Color.White.copy(alpha = (shine * 3.5f).coerceAtMost(0.9f)), w * 0.035f, Offset(w * 0.22f, h * 0.84f + w * 0.07f))
        // Soft light bouncing around the bottom.
        val r = w * 0.31f
        drawArc(
            Color.White.copy(alpha = (shine * 2f).coerceAtMost(0.5f)),
            startAngle = 35f,
            sweepAngle = 80f,
            useCenter = false,
            topLeft = Offset(w / 2 - r, bottom - w / 2 + inset - r),
            size = Size(2 * r, 2 * r),
            style = Stroke(w * 0.05f, cap = StrokeCap.Round),
        )
        // The rim, with the light catching its top, and a glint on the neck under it.
        drawPath(rimPath, rimBrush)
        drawLine(
            Color.White.copy(alpha = (shine * 3f).coerceAtMost(0.85f)),
            Offset(w * 0.2f, w * 0.035f),
            Offset(w * 0.62f, w * 0.035f),
            strokeWidth = w * 0.03f,
            cap = StrokeCap.Round,
        )
        drawLine(
            Color.White.copy(alpha = (shine * 2f).coerceAtMost(0.6f)),
            Offset(w * 0.24f, w * 0.2f),
            Offset(w * 0.42f, w * 0.2f),
            strokeWidth = w * 0.035f,
            cap = StrokeCap.Round,
        )
    }

    /** The outline in [color], with a soft glow around the outside of the tube as strong as [glow] (0 for none). */
    fun drawOutline(scope: DrawScope, color: Color, glow: Float = 0f) = with(scope) {
        if (glow > 0f) {
            clipPath(shape, ClipOp.Difference) {
                for ((width, alpha) in GLOW) {
                    drawPath(shape, color.copy(alpha = color.alpha * alpha * glow), style = Stroke(stroke * width * (0.7f + 0.3f * glow)))
                }
            }
        }
        val thick = if (glow > 0f) 1.35f else 1f
        drawPath(shape, color, style = Stroke(stroke * thick))
        // A thin bright line just inside the rim's top edge keeps the glass crisp.
        drawRoundRect(
            Color.White.copy(alpha = 0.35f),
            Offset(rim.left + stroke, rim.top + stroke * 0.9f),
            Size(rim.width - 2 * stroke, 0.01f + stroke * 0.3f),
            CornerRadius(stroke),
        )
    }

    private companion object {
        /** The glow's strokes: width in outline strokes, and alpha. */
        val GLOW = listOf(9f to 0.1f, 6f to 0.16f, 3.6f to 0.28f)
    }
}
