package io.colorsand.ui.arena

import androidx.compose.animation.Crossfade
import androidx.compose.animation.core.tween
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.runtime.staticCompositionLocalOf
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import io.colorsand.core.Arena
import io.colorsand.ui.Palette

/** The arena being played. Read it wherever the look depends on the place: the scenery, the sand, the stands. */
val LocalArena = staticCompositionLocalOf { Arena.PLAYGROUND }

/**
 * The scenery behind the board for [arena]: a painted, gently moving scene (see PlaygroundScene.kt,
 * BeachScene.kt, SeaFloorScene.kt, DesertScene.kt, BuildingSiteScene.kt, MarsScene.kt). The [palette] grades it
 * (see [SceneGrade]), so every color scheme keeps its
 * mood while the arena sets the place. Moving to another arena cross-fades from one scene to the next.
 *
 * Each scene keeps the middle of the screen, where the board sits, calm and puts its detail in the top
 * corners and along the bottom.
 */
@Composable
fun ArenaBackground(arena: Arena, palette: Palette, modifier: Modifier = Modifier) {
    val grade = remember(palette) { SceneGrade.of(palette) }
    Crossfade(arena, modifier, animationSpec = tween(SCENE_FADE_MS), label = "arena") { shown ->
        val fill = Modifier.fillMaxSize()
        when (shown) {
            Arena.PLAYGROUND -> PlaygroundScene(grade, fill)
            Arena.BUILDING_SITE -> BuildingSiteScene(grade, fill)
            Arena.BEACH -> BeachScene(grade, fill)
            Arena.SEA_FLOOR -> SeaFloorScene(grade, fill)
            Arena.DESERT -> DesertScene(grade, fill)
            Arena.MARS -> MarsScene(grade, fill)
        }
    }
}

/** How long the scenery takes to cross-fade into the next arena. */
internal const val SCENE_FADE_MS = 1100

/** The color of the arena's own sand: the ground it is set on. */
fun groundColor(arena: Arena): Color = when (arena) {
    Arena.PLAYGROUND -> Color(0xFFD9B77E)
    Arena.BUILDING_SITE -> Color(0xFFCDC2AE)
    Arena.BEACH -> Color(0xFFF1DDB0)
    Arena.SEA_FLOOR -> Color(0xFFE4DCC2)
    Arena.DESERT -> Color(0xFFE59A4F)
    Arena.MARS -> Color(0xFFC4623A)
}
