/**
 * The keepsakes of the arena being played: one themed item for every level cleared in its block of
 * [Arena.LEVELS] levels (a toy in the Playground, a crab on the Beach, a camel in the Desert, ...). They stand in
 * the scenery along the bottom corners, behind the board and clear of the controls. Solving a level pops its
 * keepsake in with a bounce, a burst of sparkles and a chime while the level-complete card is up, so clearing an
 * arena's last level shows all of its keepsakes before moving on.
 */
@Composable
fun Keepsakes(game: GameController, pours: PourAnimation, feedback: Feedback) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    var view by remember { mutableStateOf(KeepsakeView.next(null, game.levelNumber, game.unlockedLevel, game.stars, false)) }
    val pops = remember { List(Arena.LEVELS) { Animatable(1f) } }
    val bursts = remember { List(Arena.LEVELS) { Animatable(1f) } }
    LaunchedEffect(game, pours, feedback) {
        var popping: Job? = null
        snapshotFlow { KeepsakeInput(game.levelNumber, game.unlockedLevel, game.stars, game.isSolved && !pours.isRunning) }
            .collect { input ->
                val next = KeepsakeView.next(view, input.level, input.unlocked, input.stars, input.cardUp)
                if (next.block != view.block || (!input.cardUp && popping?.isActive == true)) {
                    // A new arena, or the card left before the pop: whatever was still popping in just stands there.
                    popping?.cancel()
                    pops.forEach { it.snapTo(1f) }
                    bursts.forEach { it.snapTo(1f) }
                }
                for (stage in next.fresh) {
                    pops[stage - 1].snapTo(0f)
                    bursts[stage - 1].snapTo(0f)
                }
                if (next.fresh.isNotEmpty()) {
                    popping = launch {
                        // After the card has landed and its stars have filled in.
                        delay(KEEPSAKE_DELAY_MS)
                        for (stage in next.fresh.sorted()) {
                            feedback.play(Sounds.chime(stage))
                            launch { pops[stage - 1].animateTo(1f, spring(dampingRatio = 0.42f, stiffness = Spring.StiffnessMediumLow)) }
                            launch { bursts[stage - 1].animateTo(1f, tween(900, easing = FastOutSlowInEasing)) }
                            delay(260)
                        }
                    }
                }
                view = next
            }
    }
    val arena = Arena.of(game.levelNumber)
    val clock = rememberSceneClock()
    BoxWithConstraints(Modifier.fillMaxSize().windowInsetsPadding(WindowInsets.safeDrawing)) {
        val landscape = isLandscapePhone(maxWidth, maxHeight)
        val slots = remember(maxWidth, maxHeight, landscape) { keepsakeSlots(maxWidth.value, maxHeight.value, landscape) }
        Canvas(Modifier.fillMaxSize()) {
            val shown = view.shown
            if (shown.isEmpty()) return@Canvas
            val t = clock.value
            // Back to front: the higher a keepsake stands, the further back it is.
            for (stage in KEEPSAKE_ORDER) {
                if (stage !in shown) continue
                val slot = slots[stage - 1]
                drawPopping(slot, pops[stage - 1].value, bursts[stage - 1].value) {
                    drawKeepsake(arena, stage, t, grade)
                }
            }
        }
    }
}

/** What the keepsakes follow in the game. */
private data class KeepsakeInput(val level: Int, val unlocked: Int, val stars: StarBook, val cardUp: Boolean)

/** How long after the level-complete card comes up the new keepsake pops in: once the card's stars have filled in. */
private const val KEEPSAKE_DELAY_MS = 1700L

/** The stages in drawing order, back to front (see [keepsakeSlots]: higher slots go first). */
private val KEEPSAKE_ORDER = listOf(5, 4, 3, 2, 1)

/**
 * The keepsakes of one arena block as shown: the [block] (0 for levels 1-5, 1 for 6-10, ...), the stages (1 to
 * [Arena.LEVELS]) whose keepsakes are [shown], and those of them that are [fresh]: just earned, to pop in.
 */
internal data class KeepsakeView(val block: Int, val shown: Set<Int>, val fresh: Set<Int> = emptySet()) {
    companion object {
        /** The block of [Arena.LEVELS] levels that [level] belongs to. Repeated arenas are new blocks. */
        fun blockOf(level: Int): Int = (level - 1) / Arena.LEVELS

        /**
         * The stages cleared in [level]'s block: each level there that is below the [unlocked] one (progress only
         * moves past a level by solving it) or has stars in [stars].
         */
        fun cleared(level: Int, unlocked: Int, stars: StarBook): Set<Int> {
            val first = blockOf(level) * Arena.LEVELS + 1
            return (1..Arena.LEVELS).filterTo(LinkedHashSet()) { stage ->
                val l = first + stage - 1
                l < unlocked || stars[l] > 0
            }
        }

        /**
         * The view after [prev] (null when the keepsakes first show) while playing [level]. Arriving in a block
         * shows its cleared keepsakes at once. Within a block, a keepsake the level just earned waits until the
         * level-complete card is up ([cardUp]), so it pops in with the card rather than while the sand is landing.
         */
        fun next(prev: KeepsakeView?, level: Int, unlocked: Int, stars: StarBook, cardUp: Boolean): KeepsakeView {
            val block = blockOf(level)
            val cleared = cleared(level, unlocked, stars)
            if (prev == null || prev.block != block) return KeepsakeView(block, cleared)
            val own = Arena.stage(level)
            val shown = if (!cardUp && own in cleared && own !in prev.shown) cleared - own else cleared
            return KeepsakeView(block, shown, shown - prev.shown)
        }
    }
}

/**
 * Where a keepsake stands: the left edge and the ground line of its square box, and the box's size, all in dp
 * from the top-left of the screen.
 */
internal data class KeepsakeSlot(val x: Float, val bottom: Float, val size: Float)

/**
 * The [Arena.LEVELS] keepsake slots, stage 1 first, on a [width] x [height] dp screen. Upright, the controls strip
 * sits at the bottom center ([CONTROLS_WIDTH] wide), so stages 1, 3 and 5 stand in the bottom-left corner and 2 and
 * 4 in the bottom-right, side by side where there is room and stacked up the edge where there isn't. On a phone on
 * its side ([landscape]) the controls stand in a column at the right: then the keepsakes are smaller, two stand
 * under that column and three on top of it, beside the header (or in the bottom-left corner when the header leaves
 * no room there).
 */
internal fun keepsakeSlots(width: Float, height: Float, landscape: Boolean): List<KeepsakeSlot> {
    if (landscape) {
        val columnLeft = width - SIDE_COLUMN_WIDTH
        val columnTop = height / 2 - SIDE_COLUMN_HALF_HEIGHT
        val size = (height - (height / 2 + SIDE_COLUMN_HALF_HEIGHT) - 4f).coerceIn(30f, 46f)
        val under = zone(columnLeft, SIDE_COLUMN_WIDTH, height - 2f, 2, size, level = true)
        // Over the column, right of the header (centered over the board, at most HEADER_WIDTH wide), in a row.
        val board = width - SIDE_COLUMN_WIDTH - 12f
        val headerRight = 16f + board / 2 + min(HEADER_WIDTH, board - 16f) / 2
        val topLeft = headerRight + 8f
        val overCount = floor((width - 4f - topLeft) / (size * 1.1f)).toInt().coerceIn(0, 3)
        val over = if (overCount > 0) zone(topLeft, width - 4f - topLeft, columnTop - 2f, overCount, size, mirrored = true, level = true) else emptyList()
        // What doesn't fit there stands in the bottom-left corner.
        val left = if (overCount < 3) zone(0f, size * 1.05f, height - 2f, 3 - overCount, size) else emptyList()
        return under + over + left
    }
    val side = width / 2 - CONTROLS_WIDTH / 2 - 8f
    val size = min(side * 0.8f, height * 0.1f).coerceIn(34f, 84f)
    val left = zone(0f, side, height - 6f, 3, size)
    val right = zone(width - side, side, height - 6f, 2, size, mirrored = true)
    return listOf(left[0], right[0], left[1], right[1], left[2])
}

/**
 * [count] slots of [size] in a zone [zoneWidth] wide from [zoneLeft], standing on [ground]: in a row when they fit,
 * else in a stack up the screen edge, each a little further from it. The first slot is the one nearest the edge
 * (the left edge, or the right one when [mirrored]). Side by side they stand at slightly different depths, unless
 * they stand [level] on a ledge.
 */
private fun zone(
    zoneLeft: Float,
    zoneWidth: Float,
    ground: Float,
    count: Int,
    size: Float,
    mirrored: Boolean = false,
    level: Boolean = false,
): List<KeepsakeSlot> {
    val columns = floor(zoneWidth / (size * 1.1f)).toInt().coerceIn(1, count)
    return List(count) { i ->
        val row = i / columns
        val column = i % columns
        val cell = zoneWidth / columns
        // Stacked slots step away from the edge a little, so the stack leans like a heap rather than a tower.
        val lean = if (columns == 1) min(row * size * 0.12f, max(0f, zoneWidth - size)) else 0f
        val fromEdge = column * cell + (cell - size) / 2 + lean
        val x = if (mirrored) zoneLeft + zoneWidth - fromEdge - size else zoneLeft + fromEdge
        val stagger = if (columns > 1 && !level) (column % 2) * size * 0.22f else 0f
        KeepsakeSlot(x, ground - row * size * 0.86f - stagger, size)
    }
}

/** The width of the controls strip at the bottom of an upright screen (see Hud.kt), in dp. */
private const val CONTROLS_WIDTH = 230f

/** The width of the controls column at the right of a landscape phone, its screen padding included, in dp. */
private const val SIDE_COLUMN_WIDTH = 104f

/** Half the height of that column, in dp. */
private const val SIDE_COLUMN_HALF_HEIGHT = 140f

/** The widest the header gets (see Hud.kt), in dp. */
private const val HEADER_WIDTH = 520f

/**
 * Draws a keepsake into [slot] (in dp): [art] draws in a 100-unit box standing on y = [GROUND]. [pop] grows it from
 * nothing with an overshoot, and while [burst] runs from 0 to 1 a glow and a ring of sparkles go off around it.
 */
private inline fun DrawScope.drawPopping(slot: KeepsakeSlot, pop: Float, burst: Float, art: DrawScope.() -> Unit) {
    if (pop <= 0.01f) return
    val unit = slot.size * density / 100f
    val left = slot.x * density
    val bottom = slot.bottom * density
    translate(left, bottom - 100f * unit) {
        scale(unit, unit, Offset.Zero) {
            val middle = Offset(50f, 60f)
            if (burst < 1f) {
                drawGlow(middle, 80f * (0.5f + 0.7f * burst), Color(0xFFFFF6C8).copy(alpha = 0.95f * (1f - burst)))
            }
            // Pops up from its ground point and lands with a bounce.
            translate(0f, -18f * (1f - pop).coerceAtLeast(0f)) {
                scale(pop, pop, Offset(50f, GROUND)) { art() }
            }
            if (burst > 0f && burst < 1f) sparkleRing(middle, burst)
        }
    }
}

/** Ten sparkles flying out from [center] and fading as [t] goes from 0 to 1. */
private fun DrawScope.sparkleRing(center: Offset, t: Float) {
    val reach = 34f + 46f * t
    for (k in 0 until 10) {
        val a = k * PI / 5 + 0.3
        val c = center + Offset((cos(a) * reach).toFloat(), (sin(a) * reach * 0.85f).toFloat())
        val color = if (k % 2 == 0) Color(0xFFFFE27A) else Color.White
        val r = (if (k % 3 == 0) 10f else 6.5f) * (1f - t * 0.5f)
        drawSparkle(c, r, color.copy(alpha = 1f - t))
    }
}

/** A four-pointed twinkle of radius [r] at [c]. */
internal fun DrawScope.drawSparkle(c: Offset, r: Float, color: Color) {
    drawCircle(color, r * 0.45f, c)
    drawLine(color, c - Offset(r, 0f), c + Offset(r, 0f), strokeWidth = r * 0.35f)
    drawLine(color, c - Offset(0f, r), c + Offset(0f, r), strokeWidth = r * 0.35f)
}
