package io.colorsand.ui.fx

import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.exp
import kotlin.math.sin
import kotlin.math.sqrt
import kotlin.math.cos

/** The sample rate of every sound, in Hz. Sounds are mono, as floats from -1 to 1. */
const val SAMPLE_RATE = 44100

/** The number of samples in [millis] milliseconds. */
internal fun samples(millis: Float): Int = (millis * SAMPLE_RATE / 1000f).toInt()

/** A small deterministic noise source (xorshift), so a sound renders the same every time. */
internal class Noise(seed: Int) {
    private var state = if (seed == 0) 0x2545F491 else seed

    /** White noise from -1 to 1. */
    fun next(): Float {
        state = state xor (state shl 13)
        state = state xor (state ushr 17)
        state = state xor (state shl 5)
        return (state.toFloat() / Int.MAX_VALUE).coerceIn(-1f, 1f)
    }
}

/** A biquad filter (the usual RBJ cookbook shapes), run one sample at a time. */
internal class Biquad private constructor(
    private val b0: Float, private val b1: Float, private val b2: Float,
    private val a1: Float, private val a2: Float,
) {
    private var x1 = 0f
    private var x2 = 0f
    private var y1 = 0f
    private var y2 = 0f

    fun next(x: Float): Float {
        val y = b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
        x2 = x1; x1 = x
        y2 = y1; y1 = y
        return y
    }

    companion object {
        private fun make(freq: Float, q: Float, shape: (cos: Float, alpha: Float) -> FloatArray): Biquad {
            val w = 2 * PI.toFloat() * freq / SAMPLE_RATE
            val alpha = sin(w) / (2 * q)
            val c = cos(w)
            val (b0, b1, b2) = shape(c, alpha).let { Triple(it[0], it[1], it[2]) }
            val a0 = 1 + alpha
            return Biquad(b0 / a0, b1 / a0, b2 / a0, -2 * c / a0, (1 - alpha) / a0)
        }

        fun lowPass(freq: Float, q: Float = 0.707f) = make(freq, q) { c, _ -> floatArrayOf((1 - c) / 2, 1 - c, (1 - c) / 2) }

        fun highPass(freq: Float, q: Float = 0.707f) = make(freq, q) { c, _ -> floatArrayOf((1 + c) / 2, -(1 + c), (1 + c) / 2) }

        /** Band pass with 0 dB peak gain at [freq]. */
        fun bandPass(freq: Float, q: Float) = make(freq, q) { _, alpha -> floatArrayOf(alpha, 0f, -alpha) }
    }
}

/** A sine whose pitch can glide, kept continuous by accumulating its phase. */
internal class Oscillator {
    private var phase = 0.0

    fun next(freq: Float): Float {
        val out = sin(phase).toFloat()
        phase += 2 * PI * freq / SAMPLE_RATE
        if (phase > 2 * PI) phase -= 2 * PI
        return out
    }
}

/** A decay from 1 that falls to 1/e after [tauMillis], at sample [i]. */
internal fun decay(i: Int, tauMillis: Float): Float = exp(-i / (tauMillis * SAMPLE_RATE / 1000f))

/** A pitch gliding exponentially from [from] to [to] Hz with time constant [tauMillis], at sample [i]. */
internal fun glide(i: Int, from: Float, to: Float, tauMillis: Float): Float = to + (from - to) * decay(i, tauMillis)

/** A smooth 0 -> 1 ramp over [length] samples, at sample [i] (a raised cosine). */
internal fun ramp(i: Int, length: Int): Float =
    if (i >= length) 1f else (0.5 - 0.5 * cos(PI * i / length)).toFloat()

/** Adds a bell-like note of [freq] Hz to [out], starting at sample [start]: a few sine partials, each dying away. */
internal fun addBell(out: FloatArray, start: Int, freq: Float, gain: Float, tauMillis: Float, partials: List<Pair<Float, Float>>) {
    val attack = samples(4f)
    for ((k, partial) in partials.withIndex()) {
        val (ratio, amp) = partial
        val f = freq * ratio
        if (f >= SAMPLE_RATE / 2f) continue
        val osc = Oscillator()
        // Higher partials fade sooner, which is what makes it ring like a struck bar instead of an organ.
        val tau = tauMillis / (1 + k * 0.9f)
        for (i in 0 until out.size - start) {
            out[start + i] += gain * amp * ramp(i, attack) * decay(i, tau) * osc.next(f)
        }
    }
}

/**
 * Finishes a rendered sound: scales it so its loudest sample is [peak], and fades the first and last few
 * milliseconds so it starts and ends at exactly zero (no clicks).
 */
internal fun finish(pcm: FloatArray, peak: Float): FloatArray {
    val loudest = pcm.maxOf { abs(it) }
    val scale = if (loudest > 0f) peak / loudest else 0f
    val fadeIn = minOf(samples(1.5f), pcm.size / 4)
    val fadeOut = minOf(samples(8f), pcm.size / 4)
    for (i in pcm.indices) {
        var g = scale
        if (i < fadeIn) g *= i / fadeIn.toFloat()
        val left = pcm.size - 1 - i
        if (left < fadeOut) g *= sqrt(left / fadeOut.toFloat())
        pcm[i] *= g
    }
    return pcm
}

/** [pcm] as a 16-bit mono WAV file. */
fun wav(pcm: FloatArray): ByteArray {
    val data = pcm.size * 2
    val out = ByteArray(44 + data)
    var at = 0
    fun text(s: String) = s.forEach { out[at++] = it.code.toByte() }
    fun int(v: Int, bytes: Int) = repeat(bytes) { out[at++] = (v ushr (8 * it)).toByte() }
    text("RIFF"); int(36 + data, 4); text("WAVE")
    text("fmt "); int(16, 4); int(1, 2); int(1, 2); int(SAMPLE_RATE, 4); int(SAMPLE_RATE * 2, 4); int(2, 2); int(16, 2)
    text("data"); int(data, 4)
    for (s in pcm) int(pcm16(s).toInt(), 2)
    return out
}

/** A sample as 16-bit PCM. */
fun pcm16(sample: Float): Short = (sample.coerceIn(-1f, 1f) * 32767f).toInt().toShort()
