package io.colorsand.core

/**
 * A tube holding up to [capacity] units of sand. [layers] lists the units from bottom to top.
 *
 * Tubes are immutable; pouring produces new tubes.
 */
data class Tube(val capacity: Int, val layers: List<SandColor> = emptyList()) {
    init {
        require(capacity > 0) { "Tube capacity must be positive, was $capacity" }
        require(layers.size <= capacity) { "Tube holds ${layers.size} units but capacity is $capacity" }
    }

    val size: Int get() = layers.size
    val isEmpty: Boolean get() = layers.isEmpty()
    val isFull: Boolean get() = layers.size == capacity
    val freeSpace: Int get() = capacity - layers.size
    val topColor: SandColor? get() = layers.lastOrNull()

    /** Number of contiguous units of [topColor] at the top of the tube. */
    val topRunLength: Int
        get() {
            val top = topColor ?: return 0
            var n = 0
            for (i in layers.indices.reversed()) {
                if (layers[i] != top) break
                n++
            }
            return n
        }

    /** True if the tube contains only one color (or nothing). */
    val isUniform: Boolean get() = topRunLength == size

    /** A tube is done when it is empty or completely filled with a single color. */
    val isSorted: Boolean get() = isEmpty || (isFull && isUniform)

    /** Can this tube accept [color] poured onto it? */
    fun accepts(color: SandColor): Boolean = !isFull && (isEmpty || topColor == color)

    internal fun removeTop(amount: Int): Tube = copy(layers = layers.dropLast(amount))

    internal fun add(color: SandColor, amount: Int): Tube = copy(layers = layers + List(amount) { color })

    /** Text form, bottom to top, e.g. "RRB". An empty tube is "". */
    fun encode(): String = layers.joinToString("") { it.code.toString() }

    override fun toString(): String = "[" + encode().padEnd(capacity, '.') + "]"

    companion object {
        /** Parses [encoded] (color codes, bottom to top) into a tube of [capacity]. */
        fun parse(capacity: Int, encoded: String): Tube =
            Tube(capacity, encoded.filterNot { it.isWhitespace() }.map(SandColor::fromCode))
    }
}
