package io.colorsand.ui.fx

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.selection.toggleable
import androidx.compose.material3.Switch
import androidx.compose.material3.SwitchDefaults
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.semantics.Role
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import io.colorsand.ui.LocalPalette

/** The "Sound" rows of the Colors sheet: sound effects on or off, and vibration where the device has it. */
@Composable
fun FeedbackToggles(feedback: Feedback) {
    val palette = LocalPalette.current
    Column(Modifier.padding(top = 6.dp), verticalArrangement = Arrangement.spacedBy(2.dp)) {
        Text("Sound", fontSize = 20.sp, fontWeight = FontWeight.Bold, color = palette.accent)
        ToggleRow("Sound effects", feedback.soundOn) {
            feedback.soundOn = it
            feedback.play(Sounds.click)
        }
        if (feedback.hasHaptics) {
            ToggleRow("Vibration", feedback.hapticsOn) {
                feedback.hapticsOn = it
                feedback.tick()
            }
        }
    }
}

@Composable
private fun ToggleRow(label: String, on: Boolean, onChange: (Boolean) -> Unit) {
    val palette = LocalPalette.current
    Row(
        Modifier.fillMaxWidth().toggleable(value = on, role = Role.Switch, onValueChange = onChange).padding(vertical = 4.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Text(label, color = palette.text, fontSize = 16.sp)
        Spacer(Modifier.weight(1f))
        Switch(
            checked = on,
            onCheckedChange = null,
            colors = SwitchDefaults.colors(
                checkedTrackColor = palette.accent,
                checkedThumbColor = palette.onAccent,
            ),
        )
    }
}
